<script setup lang="ts">
import {onMounted,reactive,ref,watch} from 'vue';import type {RequestFn} from './media';import {buyKey,money,date,states} from './lib';
type Row=Record<string,any>;const props=defineProps<{request:RequestFn,service:Row}>();const emit=defineEmits<{close:[],payment:[order:Row]}>();
const options=ref<Row|null>(null),quote=ref<Row|null>(null),busy=ref(false),error=ref('');const form=reactive({plan_id:'',price_id:'',coupon:'',request_key:buyKey(),renewal_of:props.service.id});
async function act(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function pay(id:string){const order=await props.request('orders/'+encodeURIComponent(id));emit('payment',order)}
async function create(){if(!quote.value)return;await act(async()=>{const d=await props.request('orders','POST',{...form,expected_payable:quote.value!.payable});await pay(d.id)})}
watch(()=>[form.price_id,form.coupon],()=>{quote.value=null;form.request_key=buyKey()});
onMounted(()=>act(async()=>{options.value=await props.request('me/renewal?service='+encodeURIComponent(props.service.id));form.plan_id=options.value!.plan.id;form.price_id=options.value!.plan.prices[0]?.id||''}));
</script>
<template><div class="modal-backdrop" @click.self="!busy&&emit('close')"><section class="modal" role="dialog" aria-modal="true" aria-label="续费此订阅"><div class="section-head"><h2>续费此订阅</h2><button :disabled="busy" @click="emit('close')" aria-label="关闭">×</button></div><div v-if="error" class="alert error" role="alert">{{error}}</div><template v-if="options"><h3>{{options.plan.name}}</h3><p class="muted mono">原订阅 {{service.id}}</p><p>当前到期：{{date(options.service.expires_at)}}</p><p v-if="options.renewal_deadline">续费截止：{{date(options.renewal_deadline)}}</p><p>同套餐剩余有效人数名额：{{options.stock_limit>0?(options.remaining_stock??0)+' 份':'不限'}}</p><p class="alert">{{options.note}}</p><p class="muted">{{options.requires_seat===false?'本次续费沿用原身份名额，套餐满额也可续费。':'原身份已过期，本次续费需预占 1 个有效人数名额。'}}</p><template v-if="options.pending_orders?.length"><h3>已有待处理续费</h3><p class="muted">此订单已预占名额，继续原订单不会重复占用。</p><article class="list-row" v-for="o in options.pending_orders" :key="o.id"><div><strong>{{money(o.payable)}} · {{states[o.state]}}</strong><small class="mono">{{o.id}}</small><small>{{o.manual_state==='submitted'?'已提交凭证，等待核验':o.state==='paid'?'已核款，正在同步续期':'付款期限 '+date(o.expires_at)}}</small></div><button v-if="o.state==='pending'" :disabled="busy" @click="act(()=>pay(o.id))">继续付款 / 查看凭证</button></article></template><form v-else-if="options.available" @submit.prevent="create"><label>续费周期<select v-model="form.price_id" required :disabled="busy"><option v-for="p in options.plan.prices" :key="p.id" :value="p.id">{{p.months}} 个月 · {{money(p.amount)}}</option></select></label><p v-if="options.recurring_coupon" class="alert">{{options.recurring_coupon.active?'已绑定循环优惠 '+options.recurring_coupon.code+'，留空自动沿用；仅首次领取计次。':'原循环优惠已停用或到期，本次不会自动优惠。'}}<small v-if="options.recurring_coupon.active">{{options.recurring_coupon.recurrence==='forever'?'永久续费优惠':('优惠截止 '+date(options.recurring_coupon.recurring_until))}} · 按当前套餐价格核算</small></p><label>其他优惠码（可选，覆盖本次自动优惠）<input v-model="form.coupon" maxlength="32" :disabled="busy"></label><button type="button" :disabled="busy||!form.price_id" @click="act(async()=>{quote=await request('checkout/quote','POST',{...form})})">核算续费金额</button><div v-if="quote" class="quote"><div><span>原价</span><strong>{{money(quote.base_amount)}}</strong></div><div><span>优惠</span><strong>−{{money(quote.discount_amount)}}</strong></div><div><span>应付</span><strong>{{money(quote.payable)}}</strong></div><p v-if="quote.coupon_note" class="muted">{{quote.coupon_note}}</p><small>支付并经后台核验后续期 {{quote.months}} 个月，原链接继续使用。</small></div><div class="modal-actions"><button type="button" :disabled="busy" @click="emit('close')">取消</button><button class="primary" :disabled="busy||!quote">创建续费订单并付款</button></div></form><p v-else class="alert error">{{options.reason||'此订阅或套餐目前不能续费，请联系管理员。'}}</p></template></section></div></template>
